package main
import("testing";"time";"net/http/httptest";"strings")
func TestActivityDefaultKeepsBeyondOldLimit(t *testing.T){s,err:=OpenStore(t.TempDir());if err!=nil{t.Fatal(err)};s.cfg.Activities=make([]Activity,2001);if err=s.AddActivity("new","detail","success");err!=nil{t.Fatal(err)};if len(s.cfg.Activities)!=2002{t.Fatal("activity truncated")}}
func TestActivityRetentionAndDeleteConfirmation(t *testing.T){s,err:=OpenStore(t.TempDir());if err!=nil{t.Fatal(err)};s.cfg.Activities=[]Activity{{Title:"old",CreatedAt:time.Now().AddDate(0,0,-20)},{Title:"new",CreatedAt:time.Now()}};app:=&App{store:s};call:=func(method,body string)int{response:=httptest.NewRecorder();app.activityPolicy(response,httptest.NewRequest(method,"/api/activity-policy",strings.NewReader(body)));return response.Code};if call("DELETE",`{"confirm":false}`)!=400||len(s.cfg.Activities)!=2{t.Fatal("unconfirmed deletion")};if call("PUT",`{"days":7,"confirm":true}`)!=200||len(s.cfg.Activities)!=1{t.Fatal("retention failed")};if call("DELETE",`{"confirm":true}`)!=200||len(s.cfg.Activities)!=0{t.Fatal("clear failed")}}
